import { Redis } from 'ioredis';
import { Request, Response, NextFunction } from 'express';

interface RateLimitConfig {
  windowMs: number;        // Time window in milliseconds
  maxRequests: number;     // Max requests per window
  keyPrefix: string;       // Redis key prefix
  skipFailedRequests: boolean;  // Don't count 4xx/5xx
  enableHeaders: boolean;  // Add X-RateLimit-* headers
  whitelist: string[];     // IPs to skip
  costFunction?: (req: Request) => number;  // Custom cost per request
}

const DEFAULT_CONFIG: RateLimitConfig = {
  windowMs: 60_000,        // 1 minute
  maxRequests: 100,
  keyPrefix: 'rl:',
  skipFailedRequests: false,
  enableHeaders: true,
  whitelist: ['127.0.0.1', '::1'],
  costFunction: undefined,
};

export class RateLimiter {
  private redis: Redis;
  private config: RateLimitConfig;
  private luaScript: string;

  constructor(redis: Redis, config: Partial<RateLimitConfig> = {}) {
    this.redis = redis;
    this.config = { ...DEFAULT_CONFIG, ...config };

    // Lua script for atomic increment + expire
    this.luaScript = `
      local key = KEYS[1]
      local window = tonumber(ARGV[1])
      local max = tonumber(ARGV[2])
      local cost = tonumber(ARGV[3])
      local now = tonumber(ARGV[4])

      local current = redis.call('GET', key)
      if current == false then
        redis.call('SET', key, cost, 'PX', window)
        return {cost, max, window}
      end

      local count = tonumber(current) + cost
      if count > max then
        local ttl = redis.call('PTTL', key)
        return {count, max, ttl}
      end

      redis.call('INCRBY', key, cost)
      local ttl = redis.call('PTTL', key)
      return {count, max, ttl}
    `;
  }

  middleware(): (req: Request, res: Response, next: NextFunction) => void {
    return async (req: Request, res: Response, next: NextFunction) => {
      const clientIp = req.ip || req.socket.remoteAddress || 'unknown';

      // Skip whitelisted IPs
      if (this.config.whitelist.includes(clientIp)) {
        return next();
      }

      const key = `${this.config.keyPrefix}${clientIp}`;
      const cost = this.config.costFunction?.(req) ?? 1;

      try {
        const result = await this.redis.eval(
          this.luaScript,
          1,
          key,
          this.config.windowMs,
          this.config.maxRequests,
          cost,
          Date.now()
        ) as [number, number, number];

        const [current, max, remaining_ms] = result;
        const remaining = Math.max(0, max - current);

        if (this.config.enableHeaders) {
          res.set({
            'X-RateLimit-Limit': String(max),
            'X-RateLimit-Remaining': String(remaining),
            'X-RateLimit-Reset': String(Math.ceil(Date.now() / 1000 + remaining_ms / 1000)),
          });
        }

        if (current > max) {
          res.set('Retry-After', String(Math.ceil(remaining_ms / 1000)));
          return res.status(429).json({
            error: 'Too Many Requests',
            retryAfter: Math.ceil(remaining_ms / 1000),
          });
        }

        // Track response status for skipFailedRequests
        if (this.config.skipFailedRequests) {
          const originalEnd = res.end;
          res.end = function(...args: any[]) {
            // Decrement counter if response was error
            if (res.statusCode >= 400) {
              // Fire and forget - don't await
              this.redis.decrby(key, cost).catch(() => {});
            }
            return originalEnd.apply(res, args);
          }.bind(this);
        }

        next();
      } catch (error) {
        // If Redis is down, allow the request (fail open)
        console.error('Rate limiter Redis error:', error);
        next();
      }
    };
  }

  async getRemainingRequests(ip: string): Promise<number> {
    const key = `${this.config.keyPrefix}${ip}`;
    const current = await this.redis.get(key);
    if (current === null) return this.config.maxRequests;
    return Math.max(0, this.config.maxRequests - parseInt(current, 10));
  }

  async resetLimit(ip: string): Promise<void> {
    const key = `${this.config.keyPrefix}${ip}`;
    await this.redis.del(key);
  }
}
