import { RateLimiter } from '../rate-limiter';
import Redis from 'ioredis-mock';
import { createRequest, createResponse } from 'node-mocks-http';

describe('RateLimiter', () => {
  let redis: any;
  let limiter: RateLimiter;

  beforeEach(() => {
    redis = new Redis();
    limiter = new RateLimiter(redis, {
      windowMs: 60_000,
      maxRequests: 5,
      keyPrefix: 'test:rl:',
    });
  });

  afterEach(async () => {
    await redis.flushall();
  });

  test('allows requests under limit', async () => {
    const middleware = limiter.middleware();
    const req = createRequest({ ip: '192.168.1.1' });
    const res = createResponse();
    const next = jest.fn();

    await middleware(req, res, next);

    expect(next).toHaveBeenCalled();
    expect(res.getHeader('X-RateLimit-Limit')).toBe('5');
    expect(res.getHeader('X-RateLimit-Remaining')).toBe('4');
  });

  test('blocks requests over limit', async () => {
    const middleware = limiter.middleware();
    const next = jest.fn();

    // Make 6 requests (limit is 5)
    for (let i = 0; i < 6; i++) {
      const req = createRequest({ ip: '10.0.0.1' });
      const res = createResponse();
      await middleware(req, res, next);

      if (i < 5) {
        expect(res.statusCode).not.toBe(429);
      } else {
        expect(res.statusCode).toBe(429);
        expect(res._getJSONData()).toHaveProperty('retryAfter');
      }
    }
    expect(next).toHaveBeenCalledTimes(5);
  });

  test('skips whitelisted IPs', async () => {
    const middleware = limiter.middleware();
    const req = createRequest({ ip: '127.0.0.1' });
    const res = createResponse();
    const next = jest.fn();

    await middleware(req, res, next);

    expect(next).toHaveBeenCalled();
    expect(res.getHeader('X-RateLimit-Limit')).toBeUndefined();
  });

  test('custom cost function', async () => {
    const costLimiter = new RateLimiter(redis, {
      windowMs: 60_000,
      maxRequests: 10,
      costFunction: (req) => req.method === 'POST' ? 3 : 1,
    });
    const middleware = costLimiter.middleware();

    // POST costs 3, so 4 POSTs = 12 > limit of 10
    for (let i = 0; i < 4; i++) {
      const req = createRequest({ method: 'POST', ip: '10.0.0.2' });
      const res = createResponse();
      const next = jest.fn();
      await middleware(req, res, next);

      if (i < 3) {
        expect(res.statusCode).not.toBe(429);
      } else {
        expect(res.statusCode).toBe(429);
      }
    }
  });
});
