import Redis from 'ioredis';

const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379';
const REDIS_MAX_RETRIES = parseInt(process.env.REDIS_MAX_RETRIES || '3', 10);
const REDIS_RETRY_DELAY_MS = parseInt(process.env.REDIS_RETRY_DELAY || '1000', 10);

export const redis = new Redis(REDIS_URL, {
  maxRetriesPerRequest: REDIS_MAX_RETRIES,
  retryStrategy: (times: number) => {
    if (times > REDIS_MAX_RETRIES) return null;
    return Math.min(times * REDIS_RETRY_DELAY_MS, 5000);
  },
  enableReadyCheck: true,
  lazyConnect: true,
});

// Health check
export async function isRedisHealthy(): Promise<boolean> {
  try {
    const result = await redis.ping();
    return result === 'PONG';
  } catch {
    return false;
  }
}
